# Expect keys: d (int), bounds (list of ints), bounds_str (str), p (int), q (int)
try:
    d = int(assign['d'])
    p = int(assign['p'])
    q = int(assign['q'])
    bounds = assign.get('bounds', None)
    # Basic validations
    import math
    if d < 2:
        # invalid dimension
        return (False, None)  # d must be at least 2
    if p <= 0 or q <= 0:
        return (False, None)  # weights must be positive
    if math.gcd(p, q) != 1:
        return (False, None)  # must be coprime so that q has inverse mod p+q
    M = p + q
    if bounds is None:
        # Attempt to parse bounds_str as a comma-separated list of ints
        bs = assign.get('bounds_str', '').strip()
        if not bs:
            return (False, None)  # No bounds provided
        try:
            bounds = [int(x) for x in bs.split(',') if x.strip() != '']
        except Exception:
            return (False, None)  # malformed bounds_str
    if len(bounds) != d:
        return (False, None)  # length mismatch
    if any(N < 0 for N in bounds):
        return (False, None)
    # Helper: modular inverse
    def inv_mod(a, m):
        r0, r1 = m, a
        s0, s1 = 1, 0
        t0, t1 = 0, 1
        while r1:
            qd = r0 // r1
            r0, r1 = r1, r0 - qd * r1
            s0, s1 = s1, s0 - qd * s1
            t0, t1 = t1, t0 - qd * t1
        if r0 != 1:
            return None
        return t0 % m
    inv_q = inv_mod(q, M)
    if inv_q is None:
        return (False, None)  # q must be invertible mod M
    c = (-p * inv_q) % M
    # residue counts per axis
    def residue_counts(N, M):
        base = (N + 1) // M
        rem = (N + 1) % M
        return [base + (1 if r < rem else 0) for r in range(M)]
    fi = [residue_counts(N, M) for N in bounds]
    # size of S
    sizeS = 1
    for N in bounds:
        sizeS *= (N + 1)
    if sizeS < 2:
        return (False, None)  # trivial set
    # compute ordered count with condition
    total = 0
    # DFS over residue vectors
    def dfs(idx, prodA, prodB):
        nonlocal total
        if idx == d:
            total += prodA * prodB
            return
        arr = fi[idx]
        for r in range(M):
            s = (c * r) % M
            dfs(idx + 1, prodA * arr[r], prodB * arr[s])
    dfs(0, 1, 1)
    ordered_with_condition = total
    # subtract equal pairs (A=B)
    ordered_distinct = ordered_with_condition - sizeS
    if ordered_distinct < 0:
        return (False, None)  # sanity check
    # unordered good and total pairs
    good_unordered = ordered_distinct // 2
    total_unordered = sizeS * (sizeS - 1) // 2
    if total_unordered == 0:
        return (False, None)
    # probability fraction
    num = ordered_with_condition - sizeS
    den = sizeS * (sizeS - 1)
    # reduce
    g = math.gcd(num, den)
    num //= g
    den //= g
    if num <= 0 or num >= den:
        # enforce non-triviality (difficulty guard)
        return (False, None)
    answer = num + den
    return True, answer
except Exception:
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

